#!/usr/bin/env node
/* eslint-disable no-console */
/**
 * AI Zen — the cover generator, shared by the SPA and the static pages.
 *
 * A cover is drawn from the article itself: the title picks the shape, the
 * author the colour. Every article gets a different one, and it costs nothing
 * to store. The static pages (generated by scripts/build.py) inline the same
 * function, so the two never drift apart.
 */

/** The five hues of the Centre. */
const HUES = [
  [78, 231, 255],   // cyan
  [167, 139, 250],  // violet
  [251, 113, 133],  // rose
  [251, 191, 36],   // amber
  [74, 222, 128],   // green
];

/**
 * Build the SVG of a cover.
 * @param {string} id    the article id, used to derive the shape
 * @param {string} author the author, used to derive the colour
 * @param {number} idx   a stable index, so two articles by the same author differ
 */
function coverSVG(id, author, idx) {
  const h = HUES[((idx || 0) * 7 + (author || '').length) % HUES.length];
  const h2 = HUES[((idx || 0) * 3 + 2) % HUES.length];
  const seed = String(id || '').split('').reduce((s, ch) => s + ch.charCodeAt(0), 0);

  const lines = [];
  for (let i = 0; i < 7; i++) {
    const y = 18 + i * 15;
    const w = 40 + ((seed * (i + 3) * 7) % 190);
    const op = (0.05 + (i % 3) * 0.04).toFixed(2);
    lines.push('<rect x="18" y="' + y + '" width="' + w + '" height="3" rx="1.5" fill="rgba(255,255,255,' + op + ')"/>');
  }

  const cx = 210 + (seed % 90);
  const cy = 34 + ((seed >> 3) % 40);
  const gid = 'azg' + (idx || 0) + '_' + String(seed % 1000);

  return '<svg viewBox="0 0 300 128" preserveAspectRatio="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">' +
    '<defs><linearGradient id="' + gid + '" x1="0" y1="0" x2="1" y2="1">' +
      '<stop offset="0" stop-color="rgba(' + h[0] + ',' + h[1] + ',' + h[2] + ',.30)"/>' +
      '<stop offset="1" stop-color="rgba(' + h2[0] + ',' + h2[1] + ',' + h2[2] + ',.08)"/>' +
    '</linearGradient></defs>' +
    '<rect width="300" height="128" fill="url(#' + gid + ')"/>' +
    '<g>' + lines.join('') + '</g>' +
    '<circle cx="' + cx + '" cy="' + cy + '" r="30" fill="none" stroke="rgba(' + h[0] + ',' + h[1] + ',' + h[2] + ',.55)" stroke-width="1.5"/>' +
    '<circle cx="' + cx + '" cy="' + cy + '" r="18" fill="rgba(' + h[0] + ',' + h[1] + ',' + h[2] + ',.22)"/>' +
    '<circle cx="' + cx + '" cy="' + cy + '" r="7" fill="rgba(' + h[0] + ',' + h[1] + ',' + h[2] + ',.85)"/>' +
  '</svg>';
}

if (typeof window !== 'undefined') {
  window.coverSVG = coverSVG;
  window.AZ_HUES = HUES;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { coverSVG, HUES };
}
